import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "../components/Navbar";
import { useLocation } from "react-router-dom";

function Feedback() {

  const location = useLocation();

  // Get event data from previous page
  const eventId = location?.state?.eventId || 1;
  const eventName = location?.state?.eventName || "College Event";

  const userId = 1; // temporary user id (until login system added)

  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(false);

  /* =========================
     LOAD FEEDBACKS
  ========================= */

  useEffect(() => {

  const loadFeedbacks = async () => {

    try {

      setLoading(true);

      const res = await axios.get(
        `http://localhost:5000/feedback/${eventId}`
      );

      if (Array.isArray(res.data)) {
        setFeedbacks(res.data);
      } else {
        setFeedbacks([]);
      }

    } catch (error) {

      console.error("Error loading feedback:", error);
      setFeedbacks([]);

    } finally {

      setLoading(false);

    }

  };

  loadFeedbacks();

}, [eventId]);

  /* =========================
     SUBMIT FEEDBACK
  ========================= */

  const submitFeedback = async () => {

    if (!comment.trim()) {
      alert("Please enter a comment");
      return;
    }

    try {

      const feedbackData = {
        user_id: userId,
        event_id: eventId,
        rating: rating,
        comment: comment
      };

      console.log("Sending feedback:", feedbackData);

      const res = await axios.post(
        "http://localhost:5000/feedback",
        feedbackData
      );

      console.log("Server response:", res.data);

      if (res.data.success) {

        alert("Feedback submitted successfully");

        setComment("");
        setRating(5);

        loadFeedbacks();

      } else {

        alert(res.data.message || "Failed to submit feedback");

      }

    } catch (error) {

      console.error("Submit feedback error:", error);

      if (error.response) {
        alert("Server error: " + error.response.data.message);
      } else {
        alert("Cannot connect to server");
      }

    }

  };

  return (

    <div>

      <Navbar />

      <div
        style={{
          padding: "20px",
          maxWidth: "600px",
          margin: "auto"
        }}
      >

        <h2>Feedback for {eventName}</h2>

        {/* Rating */}

        <div style={{ marginBottom: "15px" }}>

          <label>Rating:</label>

          <select
            value={rating}
            onChange={(e) => setRating(Number(e.target.value))}
            style={{ marginLeft: "10px" }}
          >
            <option value="1">1 Star</option>
            <option value="2">2 Star</option>
            <option value="3">3 Star</option>
            <option value="4">4 Star</option>
            <option value="5">5 Star</option>
          </select>

        </div>

        {/* Comment */}

        <div style={{ marginBottom: "15px" }}>

          <label>Comment</label>

          <textarea
            style={{
              width: "100%",
              height: "80px",
              padding: "8px"
            }}
            placeholder="Write your feedback..."
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />

        </div>

        {/* Submit Button */}

        <button
          onClick={submitFeedback}
          style={{
            padding: "10px 20px",
            cursor: "pointer",
            backgroundColor: "#007bff",
            color: "white",
            border: "none"
          }}
        >
          Submit Feedback
        </button>

        <hr />

        <h3>All Feedback</h3>

        {loading && <p>Loading feedback...</p>}

        {!loading && feedbacks.length === 0 && (
          <p>No feedback available.</p>
        )}

        {!loading && feedbacks.map((f) => (

          <div
            key={f.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px",
              borderRadius: "5px"
            }}
          >

            <p>
              <b>{f.user_name || "User"}</b> rated {f.rating}/5
            </p>

            <p>{f.comment}</p>

            <p style={{ fontSize: "12px", color: "gray" }}>
              {f.created_at
                ? new Date(f.created_at).toLocaleString()
                : ""}
            </p>

          </div>

        ))}

      </div>

    </div>

  );

}

export default Feedback;
